const n = (v, key, { min = 0, max = 1e12, allowZero = true } = {}) => {
  if (!v || v[key] === undefined || v[key] === null || (typeof v[key] === 'string' && v[key].trim() === '')) throw new Error(`${key} is required and must be numeric.`);
  const x = Number(v[key]);
  if (!Number.isFinite(x) || x < min || x > max || (!allowZero && x === 0)) throw new Error(`${key} must be a finite number between ${min} and ${max}${allowZero ? '' : ' (and greater than zero)'}.`);
  return x;
};
const pct = (v, key, max = 100) => n(v, key, { min: 0, max }) / 100;
const positiveYears = (v) => n(v, 'years', { min: 0, max: 1000 });
const pow = (a, b) => { const z = a ** b; if (!Number.isFinite(z) || z > 1e100) throw new Error('The projection is too large; reduce the rate or time period.'); return z; };
const payment = (p, annualRate, years, periods = 12) => {
  const count = years * periods, r = annualRate / periods;
  if (count === 0) return p;
  return r === 0 ? p / count : p * r / (1 - pow(1 + r, -count));
};
const compound = (principal, deposit, annualRate, years, periods = 12) => {
  const count = Math.round(years * periods), r = annualRate / periods;
  if (count === 0) return principal;
  const growth = pow(1 + r, count);
  const deposits = r === 0 ? deposit * count : deposit * ((growth - 1) / r);
  return principal * growth + deposits;
};
